import { ref, computed, watch } from '../src'

test('issue repro: sync watcher order on computed', () => {
  const logs: string[] = []
  const n = ref(0)
  const compN = computed(() => n.value)

  for (let i = 0; i < 5; i++) {
    watch(
      compN,
      v => {
        logs.push(`compN (${i}) ${v}`)
      },
      { flush: 'sync' },
    )
  }

  for (let i = 0; i < 5; i++) {
    watch(
      n,
      v => {
        logs.push(`n (${i}) ${v}`)
      },
      { flush: 'sync' },
    )
  }

  n.value++

  expect(logs).toEqual([
    'compN (0) 1',
    'compN (1) 1',
    'compN (2) 1',
    'compN (3) 1',
    'compN (4) 1',
    'n (0) 1',
    'n (1) 1',
    'n (2) 1',
    'n (3) 1',
    'n (4) 1',
  ])
})

import { ref, computed, watch } from '../src'

test('issue repro: sync watcher order on computed', () => {
  const logs: string[] = []
  const n = ref(0)
  const compN = computed(() => n.value)

  for (let i = 0; i < 5; i++) {
    watch(
      compN,
      v => {
        logs.push(`compN (${i}) ${v}`)
      },
      { flush: 'sync' },
    )
  }

  n.value++

  expect(logs).toEqual([
    'compN (0) 1',
    'compN (1) 1',
    'compN (2) 1',
    'compN (3) 1',
    'compN (4) 1',
  ])
})

import { ref, computed, effect } from '../src'

test('issue repro: sync watcher order on computed', () => {
  const logs: string[] = []
  const n = ref(0)
  const compN = computed(() => n.value)

  for (let i = 0; i < 5; i++) {
    effect(
      () => compN.value,
      {
        scheduler: () => logs.push(`compN (${i}) ${compN.value}`),
      },
    )
  }

  for (let i = 0; i < 5; i++) {
    effect(
      () => n.value,
      {
        scheduler: () => logs.push(`n (${i}) ${n.value}`),
      },
    )
  }

  n.value++

  expect(logs).toEqual([
    'compN (0) 1',
    'compN (1) 1',
    'compN (2) 1',
    'compN (3) 1',
    'compN (4) 1',
    'n (0) 1',
    'n (1) 1',
    'n (2) 1',
    'n (3) 1',
    'n (4) 1',
  ])
})

